gaj7(){return"2. \u5df2\u6ee1 14 \u5468\u5c81\u3001\u4e0d\u6ee1 18 \u5468\u5c81\u7684\u672a\u6210\u5e74\u4eba\u4f7f\u7528\u672c\u670d\u52a1,\u5e94\u5f53\u53d6\u5f97\u76d1\u62a4\u4eba\u540c\u610f\u5e76\u5728\u5176\u6307\u5bfc\u4e0b\u4f7f\u7528\u3002\u76d1\u62a4\u4eba\u672a\u540c\u610f\u7684,\u53ef\u901a\u8fc7\u7b2c\u5341\u56db\u7ae0\u7684\u8054\u7cfb\u65b9\u5f0f\u901a\u77e5\u5e73\u53f0,\u5e73\u53f0\u5c06\u4f9d\u6cd5\u5904\u7406\u76f8\u5173\u8d26\u53f7\u3002"},
gaj8(){return"3. \u5e73\u53f0\u4e0d\u5236\u4f5c\u3001\u4e0d\u63a8\u9001\u8bf1\u5bfc\u672a\u6210\u5e74\u4eba\u6c89\u8ff7\u7684\u5185\u5bb9,\u4e0d\u8bbe\u7f6e\u4efb\u4f55\u8bf1\u5bfc\u6027\u6253\u8d4f\u6216\u6d88\u8d39\u529f\u80fd;\u53d1\u73b0\u53ef\u80fd\u5f71\u54cd\u672a\u6210\u5e74\u4eba\u8eab\u5fc3\u5065\u5eb7\u7684\u5185\u5bb9,\u5e73\u53f0\u5c06\u4f9d\u6cd5\u5904\u7f6e\u3002"},
gaj9(){return"4. \u53d1\u5e03\u542b\u6709\u672a\u6210\u5e74\u4eba\u5f62\u8c61\u7684\u4f5c\u54c1,\u5e94\u5f53\u4f9d\u6cd5\u53d6\u5f97\u5176\u76d1\u62a4\u4eba\u7684\u540c\u610f\u3002"},
gajf(){return"\u5341\u4e8c\u3001\u534f\u8bae\u7684\u4fee\u6539\u4e0e\u901a\u77e5"},
gajb(){return"1. \u6211\u4eec\u53ef\u80fd\u56e0\u6cd5\u5f8b\u6cd5\u89c4\u53d8\u5316\u3001\u76d1\u7ba1\u8981\u6c42\u6216\u670d\u52a1\u8c03\u6574\u4fee\u6539\u672c\u534f\u8bae\u3002\u4fee\u6539\u540e\u7684\u534f\u8bae\u5c06\u5728\u751f\u6548\u524d\u81f3\u5c11 7 \u65e5\u5728 App \u5185\u516c\u793a;\u5bf9\u60a8\u6743\u5229\u4e49\u52a1\u6709\u91cd\u5927\u5f71\u54cd\u7684\u4fee\u6539,\u516c\u793a\u4e0d\u5c11\u4e8e 15 \u65e5\u3002"},
gajc(){return"2. \u60a8\u4e0d\u540c\u610f\u4fee\u6539\u5185\u5bb9\u7684,\u6709\u6743\u505c\u6b62\u4f7f\u7528\u672c\u670d\u52a1\u5e76\u6ce8\u9500\u8d26\u53f7,\u6ce8\u9500\u524d\u7684\u6743\u5229\u4e49\u52a1\u6309\u4fee\u6539\u524d\u7684\u534f\u8bae\u6267\u884c;\u516c\u793a\u671f\u6ee1\u540e\u60a8\u7ee7\u7eed\u4f7f\u7528\u672c\u670d\u52a1\u7684,\u89c6\u4e3a\u63a5\u53d7\u4fee\u6539\u540e\u7684\u534f\u8bae\u3002\u6211\u4eec\u4e0d\u4f1a\u5c06\u4fee\u6539\u8bbe\u5b9a\u4e3a\u9ed8\u8ba4\u540c\u610f\u7684\u9009\u9879\u3002"},
gajd(){return"3. \u6211\u4eec\u4fdd\u7559\u672c\u534f\u8bae\u7684\u5386\u53f2\u7248\u672c,\u60a8\u53ef\u901a\u8fc7\u7b2c\u5341\u56db\u7ae0\u7684\u8054\u7cfb\u65b9\u5f0f\u7d22\u53d6\u3002"},
gaje(){return"4. \u5e73\u53f0\u5411\u60a8\u53d1\u51fa\u7684\u901a\u77e5,\u53ef\u4ee5\u901a\u8fc7 App \u5185\u516c\u544a\u3001\u7cfb\u7edf\u901a\u77e5\u3001\u9875\u9762\u63d0\u793a\u3001\u60a8\u7ed1\u5b9a\u7684\u624b\u673a\u53f7\u6216\u7535\u5b50\u90ae\u7bb1\u7b49\u65b9\u5f0f\u4f5c\u51fa,\u81ea\u53d1\u5e03\u6216\u53d1\u9001\u4e4b\u65e5\u89c6\u4e3a\u9001\u8fbe;\u60a8\u5411\u5e73\u53f0\u53d1\u51fa\u7684\u901a\u77e5,\u5e94\u901a\u8fc7\u7b2c\u5341\u56db\u7ae0\u516c\u5e03\u7684\u8054\u7cfb\u65b9\u5f0f\u4f5c\u51fa\u3002"},
gajm(){return"\u5341\u4e09\u3001\u6cd5\u5f8b\u9002\u7528\u4e0e\u4e89\u8bae\u89e3\u51b3"},
gajg(){return"1. \u672c\u534f\u8bae\u7684\u8ba2\u7acb\u3001\u6548\u529b\u3001\u89e3\u91ca\u4e0e\u4e89\u8bae\u89e3\u51b3,\u9002\u7528\u4e2d\u534e\u4eba\u6c11\u5171\u548c\u56fd(\u4e3a\u672c\u534f\u8bae\u4e4b\u76ee\u7684,\u4e0d\u542b\u6e2f\u6fb3\u53f0\u5730\u533a)\u6cd5\u5f8b\u3002"},
gajh(){return"2. \u56e0\u672c\u534f\u8bae\u4ea7\u751f\u7684\u4e89\u8bae,\u53cc\u65b9\u5e94\u53cb\u597d\u534f\u5546;\u534f\u5546\u4e0d\u6210\u7684,\u4efb\u4f55\u4e00\u65b9\u5747\u53ef\u5411\u3010\u516c\u53f8\u6ce8\u518c\u5730\u5f85\u5b9a\u540e\u586b\u5199\u3011\u6709\u7ba1\u8f96\u6743\u7684\u4eba\u6c11\u6cd5\u9662\u63d0\u8d77\u8bc9\u8bbc\u3002"},
gaji(){return"3. \u672c\u534f\u8bae\u4efb\u4e00\u6761\u6b3e\u88ab\u8ba4\u5b9a\u65e0\u6548\u6216\u4e0d\u53ef\u6267\u884c\u7684,\u4e0d\u5f71\u54cd\u5176\u4f59\u6761\u6b3e\u7684\u6548\u529b\u3002"},
gajj(){return"4. \u672c\u534f\u8bae\u6807\u9898\u4ec5\u4e3a\u65b9\u4fbf\u9605\u8bfb\u800c\u8bbe,\u4e0d\u4f5c\u4e3a\u89e3\u91ca\u6761\u6b3e\u542b\u4e49\u7684\u4f9d\u636e\u3002"},
