gajl(){return"6. \u672c\u534f\u8bae\u53ca\u5176\u7ec4\u6210\u6587\u4ef6\u6784\u6210\u53cc\u65b9\u5c31\u76f8\u5173\u4e8b\u9879\u7684\u5b8c\u6574\u7ea6\u5b9a\u3002"},
gajq(){return"\u5341\u56db\u3001\u8054\u7cfb\u6211\u4eec"},
gajn(){return"\u8fd0\u8425\u8005:\u3010\u516c\u53f8\u540d\u79f0\u5f85\u6ce8\u518c\u540e\u586b\u5199\u3011"},
gajo(){return"\u8054\u7cfb\u90ae\u7bb1:\u3010\u8054\u7cfb\u90ae\u7bb1\u5f85\u586b\u5199 \u2014\u2014 \u4e0a\u7ebf\u524d\u5fc5\u987b\u66ff\u6362\u4e3a\u771f\u5b9e\u53ef\u8fbe\u90ae\u7bb1,\u4e0e\u5e73\u53f0\u516c\u7ea6\u9875\u3001\u9690\u79c1\u653f\u7b56\u540c\u4e00\u4e2a\u3011"},
